const familyStories={
core:{explain:"شایستگی‌هایی که در هر واحد و هر سطحی به درد می‌خورند؛ مثل تعریف روشن مسئله، استفاده از داده معتبر و پاسخ‌گویی به نتیجه.",story:"در سه شیفت، خروجی خط پایین آمده است. یک نفر می‌گوید مواد بی‌کیفیت بوده و دیگری می‌گوید دستگاه ایراد دارد. به‌جای قضاوت، تیم زمان توقف‌ها و شرایط مواد را ثبت می‌کند و فرضیه‌ها را می‌سنجد.",good:"مسئله با عدد و زمان تعریف و یک فرضیه آزموده می‌شود.",bad:"بدون بررسی، یک واحد یا یک نفر مقصر شناخته می‌شود.",evidence:"تعریف مسئله، داده قابل اتکا و نتیجه آزمون علت"},
managerial:{explain:"کارهایی که از مدیر انتظار می‌رود برای پیشبرد کار از طریق دیگران انجام دهد: برنامه‌ریزی، سازماندهی، هدایت، تفویض، تصمیم و کنترل.",story:"سرپرست می‌بیند سفارش فوری با کار تعمیراتی همان شیفت تداخل دارد. ابتدا اولویت‌ها را روشن می‌کند، ظرفیت امن را می‌سنجد، مسئول هر کار و زمان بازبینی را تعیین می‌کند.",good:"خروجی، مالک، حدود اختیار و زمان کنترل روشن است.",bad:"فقط دستور «زودتر تمام کنید» داده می‌شود.",evidence:"برنامه اجرایی با مسئول، موعد و کنترل ریسک"},
functional:{explain:"دانش و مهارت فنی ویژه همان شغل؛ برای مثال برنامه‌ریزی تولید، آزمایشگاه کنترل کیفیت، نگهداری تجهیزات یا مدیریت مالی.",story:"کارشناس کیفیت باید نتیجه یک آزمون مرزی را تفسیر کند. مدیر نباید بدون صلاحیت فنی نتیجه را تغییر دهد؛ باید از مرجع تخصصی و روش مصوب استفاده شود.",good:"تصمیم فنی به فرد صاحب‌صلاحیت و استاندارد مصوب سپرده می‌شود.",bad:"برای حفظ موعد تحویل، نتیجه آزمون دستکاری می‌شود.",evidence:"آزمون شغلی و مشاهده عملکرد فنی مستقل؛ این دوره عمومی آن را نمره نمی‌دهد"},
business:{explain:"دیدن پیامد تصمیم برای کل زنجیره از تأمین تا مشتری: هزینه، کیفیت، ظرفیت، تحویل و سودآوری واقعی.",story:"فروش سفارش را موفق ثبت کرده؛ تولید محصول را آماده می‌داند اما کیفیت آن را آزاد نکرده و ارسال دوم هزینه زیادی دارد. معیار مشترک، تحویل مجاز و سود واقعی است.",good:"درباره مشتری، کیفیت و هزینه کل تصمیم مشترک گرفته می‌شود.",bad:"هر واحد فقط شاخص خودش را موفق اعلام می‌کند.",evidence:"تصمیم مشترک و اثر آن بر شاخص‌های زنجیره"},
personal:{explain:"توان اداره خود در شرایط فشار، پذیرش مسئولیت، انعطاف در قضاوت و اصلاح رفتار پس از دریافت بازخورد.",story:"مدیر از گزارش دیرهنگام ناراحت است. قبل از واکنش، بین «گزارش دیر رسیده» و «همکار بی‌مسئولیت است» تفاوت می‌گذارد و مانع واقعی را می‌پرسد.",good:"پیش از قضاوت مکث می‌کند و فرض خود را می‌آزماید.",bad:"از یک رویداد، درباره شخصیت طرف مقابل حکم کلی می‌دهد.",evidence:"رفتار مشاهده‌شده در شرایط فشار و اصلاح بعدی"},
interpersonal:{explain:"توان گفت‌وگو، شنیدن، حل تعارض، ارائه بازخورد، هماهنگی و توسعه توان دیگران.",story:"تولید خواستار خروج فوری محموله است، کیفیت به آزمون تکمیلی نیاز دارد. طرفین به‌جای مقصرسازی، نگرانی‌ها را می‌شنوند و بر زمان گزارش، مسئول پیگیری و ممنوعیت خروج بدون مجوز توافق می‌کنند.",good:"نگرانی هر دو طرف شنیده شده و توافق اجرایی با موعد شکل می‌گیرد.",bad:"لحن مؤدب است ولی هیچ اقدام یا مسئول مشخصی تعیین نمی‌شود.",evidence:"گفت‌وگوی توصیفی و توافق قابل پیگیری"}
};
for(const f of data.families){if(familyStories[f.id])Object.assign(f,familyStories[f.id]);}
const familyPractice={"core":["دو سرپرست تولید و کیفیت اختلاف علت تأخیر را با تفکیک واقعیت و فرض و جمع‌آوری شاهد معتبر بررسی کنند.","مدیران کیفیت، عملیات و فروش علت‌های افت تحویل را با داده مشترک بسنجند، نه با سرزنش واحدها.","اگر شواهد تازه فرض اولیه را رد کرد، کدام تصمیم را تغییر می‌دهید؟"],"managerial":["سرپرستان تولید و تعمیرات بدون دستور به کارکنان واحد مقابل، درباره مالک اقدام، زمان وضعیت و مرز اختیار توافق کنند.","مدیران عملیات و منابع انسانی ظرفیت، صلاحیت افراد، منابع و نقاط کنترل را به یک تعهد مشترک تبدیل کنند.","تفاوت واگذاری کار به دیگری با ساختن تعهد بین‌واحدی چیست؟"],"functional":["سرپرست تولید درباره محدودیت فنی سرپرست کیفیت سؤال کند؛ هیچ‌کدام مجوز تخصصی را صادر نکند.","مدیر کیفیت استقلال ارزیابی فنی را حفظ و مدیر فروش سناریوی تجاری مجاز پیشنهاد کند.","کدام تصمیم باید حتماً در اختیار صاحب‌صلاحیت فنی باقی بماند؟"],"business":["سرپرستان انبار و ارسال هزینه توقف و خطر خطای ردیابی را در یک تصویر مشترک ببینند.","مدیران فروش، عملیات، کیفیت و مالی سه سناریوی تحویل را از نظر مشتری، سود و ریسک مقایسه کنند.","کدام انتخاب شاخص یک واحد را بهتر ولی نتیجه شرکت را بدتر می‌کند؟"],"personal":["سرپرست تولید فرض «کیفیت بی‌مسئولیت است» را با سؤال باز و گوش‌دادن به شاهد اصلاح کند.","مدیر عملیات هنگام اختلاف با مدیر منابع انسانی لحن دفاعی‌اش را تشخیص داده و درخواست داده کند.","چه زمانی فرض ذهنی‌تان درباره دیگری را به‌جای واقعیت به کار بردید؟"],"interpersonal":["دو سرپرست هم‌سطح نگرانی یکدیگر را بازتاب دهند و روی اقدام، مالک و موعد توافق کنند.","چهار مدیر با منافع و شاخص‌های متفاوت، جلسه‌ای دشوار را به تصمیم مشترک برسانند.","کدام جمله هم تنش را کاهش داد و هم اطلاعات معتبر تازه ایجاد کرد؟"]};
for(const f of data.families){const p=familyPractice[f.id];if(p){f.supervisorPractice=p[0];f.managerPractice=p[1];f.reflectionQuestion=p[2];}}
g.BPUpgradeData=changes;
